import 'package:flutter/material.dart';

class DeadlineCalculatorScreen extends StatefulWidget {
  const DeadlineCalculatorScreen({super.key});

    @override
      State<DeadlineCalculatorScreen> createState() => _DeadlineCalculatorScreenState();
      }

      class _DeadlineCalculatorScreenState extends State<DeadlineCalculatorScreen> {
        DateTime _judgmentDate = DateTime.now();
          int _selectedDays = 10; // المدة الافتراضية للطعن أو الاستئناف (مثلاً 10 أيام أو 30 يوماً)
            DateTime? _resultDate;

              // دالة حساب الميعاد النهائي
                void _calculateDeadline() {
                    setState(() {
                          // إضافة عدد الأيام القانونية لتاريخ صدور الحكم
                                _resultDate = _judgmentDate.add(Duration(days: _selectedDays));
                                    });
                                      }

                                        Future<void> _pickJudgmentDate(BuildContext context) async {
                                            final DateTime? picked = await showDatePicker(
                                                  context: context,
                                                        initialDate: _judgmentDate,
                                                              firstDate: DateTime(2020),
                                                                    lastDate: DateTime(2030),
                                                                        );
                                                                            if (picked != null && picked != _judgmentDate) {
                                                                                  setState(() {
                                                                                          _judgmentDate = picked;
                                                                                                });
                                                                                                    }
                                                                                                      }

                                                                                                        @override
                                                                                                          Widget build(BuildContext context) {
                                                                                                              return Scaffold(
                                                                                                                    appBar: AppBar(
                                                                                                                            title: const Text('حاسبة المهل القانونية'),
                                                                                                                                    backgroundColor: const Color(0xFF1A237E),
                                                                                                                                            centerTitle: true,
                                                                                                                                                  ),
                                                                                                                                                        body: Padding(
                                                                                                                                                                padding: const EdgeInsets.all(16.0),
                                                                                                                                                                        child: Column(
                                                                                                                                                                                  crossAxisAlignment: CrossAxisAlignment.stretch,
                                                                                                                                                                                            children: [
                                                                                                                                                                                                        const Text(
                                                                                                                                                                                                                      'احسب الموعد النهائي للطعن أو استئناف الأحكام وفقاً للمدد القانونية:',
                                                                                                                                                                                                                                    style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold),
                                                                                                                                                                                                                                                ),
                                                                                                                                                                                                                                                            const SizedBox(height: 20),
                                                                                                                                                                                                                                                                        Row(
                                                                                                                                                                                                                                                                                      mainAxisAlignment: MainAxisAlignment.between,
                                                                                                                                                                                                                                                                                                    children: [
                                                                                                                                                                                                                                                                                                                    Text(
                                                                                                                                                                                                                                                                                                                                      'تاريخ صدور الحكم: ${_judgmentDate.toString().split(' ')[0]}',
                                                                                                                                                                                                                                                                                                                                                        style: const TextStyle(fontSize: 15),
                                                                                                                                                                                                                                                                                                                                                                        ),
                                                                                                                                                                                                                                                                                                                                                                                        ElevatedButton(
                                                                                                                                                                                                                                                                                                                                                                                                          onPressed: () => _pickJudgmentDate(context),
                                                                                                                                                                                                                                                                                                                                                                                                                            child: const Text('اختر التاريخ'),
                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                          ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const SizedBox(height: 20),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              TextField(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            keyboardType: TextInputType.number,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          decoration: const InputDecoration(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          labelText: 'المدة القانونية بالأيام (مثال: 10 أو 30 يوماً)',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          border: OutlineInputBorder(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onChanged: (value) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      setState(() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        _selectedDays = int.tryParse(value) ?? 10;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const SizedBox(height: 30),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ElevatedButton(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        style: ElevatedButton.styleFrom(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        backgroundColor: const Color(0xFF1A237E),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        padding: const EdgeInsets.symmetric(vertical: 14),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onPressed: _calculateDeadline,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  child: const Text(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'احسب تاريخ انتهاء المهل',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  style: TextStyle(fontSize: 18, color: Colors.white),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const SizedBox(height: 30),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (_resultDate != null)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Card(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  color: Colors.indigo.shade50,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  child: Padding(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    padding: const EdgeInsets.all(16.0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      child: Column(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const Text(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'آخر موعد قانوني لتقديم الطعن/الاستئناف:',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                style: TextStyle(fontSize: 15, color: Colors.black87),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const SizedBox(height: 8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Text(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          _resultDate.toString().split(' ')[0],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  style: const TextStyle(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            fontSize: 22,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      fontWeight: FontWeight.bold,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                color: Color(0xFF1A237E),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                